-- Arbeitsrecht Berufsbildung > Rechte von Auszubildenden > Anspruch auf Zeugnis bei Beendigung (§ 16 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Hat ein Fachinformatiker nach der IHK-Abschlussprüfung Anspruch auf ein Zeugnis?', 2, '[{"text": "Ja", "correct": true, "because": "§ 16 BBiG garantiert das Zeugnis bei Beendigung"}, {"text": "Nein", "correct": false, "because": "Der Anspruch ist gesetzlich festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ausbildungsbetrieb das Zeugnis eines Fachinformatikers verweigern, wenn er die Prüfung nicht besteht?', 2, '[{"text": "Nein", "correct": true, "because": "§ 16 BBiG gilt unabhängig vom Prüfungsergebnis"}, {"text": "Ja", "correct": false, "because": "Der Anspruch ist nicht an den Erfolg gekoppelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss das Zeugnis eines Fachinformatikers handschriftlich ausgestellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "§ 16 BBiG fordert keine Handschrift"}, {"text": "Ja", "correct": false, "because": "Digitale oder gedruckte Form ist zulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker ein Zeugnis verlangen, wenn er selbst kündigt?', 2, '[{"text": "Ja", "correct": true, "because": "§ 16 BBiG gilt bei jeder Beendigung"}, {"text": "Nein", "correct": false, "because": "Der Anspruch ist unabhängig von der Kündigungsart"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Ausbildungsbetrieb verpflichtet, ein Zeugnis auch bei einer außerordentlichen Kündigung auszustellen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 16 BBiG macht keine Ausnahmen"}, {"text": "Nein", "correct": false, "because": "Der Anspruch bleibt bestehen"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage gibt einem Fachinformatiker Anspruch auf ein Zeugnis bei Beendigung?', 2, '[{"text": "§ 16 BBiG", "correct": true, "because": "Regelt den Zeugnisanspruch"}, {"text": "§ 17 BBiG", "correct": false, "because": "Bezieht sich auf Vergütung"}, {"text": "§ 14 BBiG", "correct": false, "because": "Regelt Ausbildungspflichten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Fachinformatiker tun, um sein Zeugnis nach § 16 BBiG zu erhalten?', 3, '[{"text": "Es beim Betrieb anfordern", "correct": true, "because": "Der Anspruch muss aktiv geltend gemacht werden"}, {"text": "Die IHK-Prüfung bestehen", "correct": false, "because": "Nicht Voraussetzung"}, {"text": "Ein Jahr warten", "correct": false, "because": "Zeugnis ist sofort fällig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Angabe muss im Zeugnis eines Fachinformatikers zwingend enthalten sein?', 3, '[{"text": "Dauer der Ausbildung", "correct": true, "because": "§ 16 BBiG fordert wesentliche Angaben"}, {"text": "Lieblingsprogrammiersprache", "correct": false, "because": "Irrelevant für das Zeugnis"}, {"text": "Anzahl der Fehltage", "correct": false, "because": "Nicht zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verpflichtet, einem Fachinformatiker ein Zeugnis auszustellen?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 16 BBiG legt das fest"}, {"text": "Die IHK", "correct": false, "because": "IHK stellt nur Prüfungszeugnisse aus"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule ist nicht zuständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Betrieb das Zeugnis eines Fachinformatikers nicht ausstellt?', 3, '[{"text": "Der Auszubildende kann es einklagen", "correct": true, "because": "§ 16 BBiG ist einklagbar"}, {"text": "Der Anspruch verfällt", "correct": false, "because": "Der Anspruch bleibt bestehen"}, {"text": "Die Berufsschule übernimmt es", "correct": false, "because": "Schule hat keine Pflicht"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Angaben müssen im Zeugnis eines Fachinformatikers nach § 16 BBiG enthalten sein?', 4, '[{"text": "Dauer der Ausbildung", "correct": true, "because": "Wesentlich nach § 16 BBiG"}, {"text": "Art der Ausbildung", "correct": true, "because": "Muss angegeben werden"}, {"text": "Persönliche Hobbys", "correct": false, "because": "Nicht relevant"}, {"text": "Berufsschulnoten", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzungen muss ein Fachinformatiker erfüllen, um ein Zeugnis nach § 16 BBiG zu erhalten?', 3, '[{"text": "Das Ausbildungsverhältnis beenden", "correct": true, "because": "Grundvoraussetzung"}, {"text": "Mindestens ein Jahr im Betrieb sein", "correct": false, "because": "Dauer ist egal"}, {"text": "Das Zeugnis anfordern", "correct": true, "because": "Muss aktiv eingefordert werden"}, {"text": "Die IHK-Prüfung bestehen", "correct": false, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kann ein Fachinformatiker tun, wenn das Zeugnis fehlerhaft ist?', 4, '[{"text": "Korrektur verlangen", "correct": true, "because": "Zeugnis muss wahrheitsgemäß sein"}, {"text": "Den Betrieb verklagen", "correct": true, "because": "Bei Verweigerung möglich"}, {"text": "Es ignorieren", "correct": false, "because": "Wichtig für Bewerbungen"}, {"text": "Selbst ein Zeugnis schreiben", "correct": false, "because": "Nicht rechtsgültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Zeugnissen kann ein Fachinformatiker nach § 16 BBiG verlangen?', 3, '[{"text": "Einfaches Zeugnis", "correct": true, "because": "Mindestanforderung"}, {"text": "Qualifiziertes Zeugnis", "correct": true, "because": "Mit Leistungsbeurteilung möglich"}, {"text": "Zeugnis über Gehalt", "correct": false, "because": "Nicht Teil von § 16 BBiG"}, {"text": "Zeugnis über Fehlzeiten", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen darf ein Betrieb im Zeugnis eines Fachinformatikers nicht angeben?', 3, '[{"text": "Dauer der Ausbildung", "correct": false, "because": "Muss enthalten sein"}, {"text": "Private Krankheitsdetails", "correct": true, "because": "Datenschutzrechtlich verboten"}, {"text": "Bewertung der Leistung", "correct": false, "because": "Kann enthalten sein"}, {"text": "Falsche Angaben", "correct": true, "because": "Zeugnis muss wahrheitsgemäß sein"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Zeugnis eines Fachinformatikers muss die IHK-Prüfung erwähnen. b) § 16 BBiG verpflichtet den Betrieb zur Ausstellung.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Prüfung ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "§ 16 BBiG ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Fachinformatiker kann ein qualifiziertes Zeugnis verlangen. b) Das Zeugnis muss nur auf Englisch ausgestellt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualifiziertes Zeugnis möglich, Englisch nicht Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Zeugnis eines Fachinformatikers muss immer die Leistung bewerten. b) Der Anspruch gilt auch bei Kündigung in der Probezeit.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Bewertung optional"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Anspruch gilt immer"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Fachinformatiker verliert den Zeugnisanspruch bei Fehlverhalten. b) Das Zeugnis muss schriftlich ausgestellt werden.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Fehlverhalten ändert nichts"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Schriftform ist üblich"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Zeugnis eines Fachinformatikers muss den Ausbildungsberuf nennen. b) Der Betrieb kann das Zeugnis ohne Aufforderung ausstellen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beruf ist Pflicht, Aufforderung oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht zwingend"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

